import React, { forwardRef, useReducer } from 'react';
import styled, { CSSObject } from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Typography from '@dynatrace/strato-design-tokens/typography';

import { SharedInputPropsContext } from '../../../../core/contexts/SharedInputPropsContext.js';
import { _useSharedInputPropsContext } from '../../../../core/hooks/useSharedInputPropsContext.js';
import type { DataTestId } from '../../../../core/types/data-props.js';
import type { StylingProps } from '../../../../core/types/styling-props.js';
import type { WithChildren } from '../../../../core/types/with-children.js';
import { Flex } from '../../../../layouts-core/flex/Flex.js';
import { _FormFieldContext as FormFieldContext } from '../../contexts/FormFieldContext.js';
import { _formFieldReducer } from '../../state/formfield-state-reducer.js';

export interface FieldSetProps extends WithChildren, StylingProps, DataTestId {
  /** The legend used to describe the fieldset. */
  legend?: string;
  /**
   * Whether the fieldset and all its fields are disabled or not.
   * @defaultValue false
   */
  disabled?: boolean;
  /** The name associated with the group in a form. */
  name?: string;
}

// #region StyledComponents
const StyledFieldSet = /* @__PURE__ */ styled('fieldset')({
  appearance: 'none',
  margin: 0,
  border: 'none',
  padding: 0,
  /* override the flexbox default settings of 'auto' to enable a min width less than the content width. */
  minWidth: 0,
  /* override the flexbox default settings of 'auto' to enable a min height less than the content height. */
  minHeight: 0,
});

const StyledHeading = /* @__PURE__ */ styled('legend')({
  padding: 0,
  appearance: 'none',

  marginBottom: Spacings.Size12,

  fontFamily: Typography.Heading.Level3.Family,
  fontSize: Typography.Heading.Level3.Size,
  fontWeight: Typography.Heading.Level3.Weight,
  lineHeight: Typography.Heading.Level3.LineHeight,
  textTransform: Typography.Heading.Level3.TextTransform,
  textDecoration: Typography.Heading.Level3.TextDecoration,
} as CSSObject);

// #endregion

/**
 * The `FieldSet` component groups related fields under the same heading.
 * The legend assigns a caption to the `FieldSet` to improve accessibility.
 */
export const FieldSet = forwardRef<HTMLFieldSetElement, FieldSetProps>(
  (props, forwardedRef) => {
    const {
      children,
      legend,
      disabled: propDisabled = false,
      name,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: FieldSetProps = props;

    const { disabled } = _useSharedInputPropsContext({
      disabled: propDisabled,
    });

    const [formFieldState, formFieldDispatch] = useReducer(_formFieldReducer, {
      disabled: propDisabled,
    });

    return (
      <StyledFieldSet
        data-testid={dataTestId}
        ref={forwardedRef}
        name={name}
        className={consumerClassName}
        style={consumerStyle}
        {...remainingProps}
      >
        {legend && <StyledHeading>{legend}</StyledHeading>}
        <FormFieldContext.Provider
          value={{
            disabled: formFieldState.disabled || propDisabled,
            required: !!formFieldState.required,
            dispatch: formFieldDispatch,
          }}
        >
          <SharedInputPropsContext.Provider value={{ disabled }}>
            <Flex gap={12} flexDirection="column">
              {children}
            </Flex>
          </SharedInputPropsContext.Provider>
        </FormFieldContext.Provider>
      </StyledFieldSet>
    );
  },
);
(FieldSet as typeof FieldSet & { displayName: string }).displayName =
  'FieldSet';
